package com.example.data

object ChantalTrailLife {
    val encounters = listOf(
        "У тропы улитка продаёт скорость. Пока очередь двигается быстрее продавца." to "Скоростью оказалась записка «Не тащи лишнее». Я оставила ненужный камешек. Работает!",
        "Встретила мышонка с огромной ложкой. Говорит, идёт сражаться с кашей." to "Каша победила: он съел две миски и уснул. Ложку поставили рядом, как памятник герою.",
        "Ёж несёт яблоко и сердится на звон. Кажется, яблоко музыкальное." to "Под яблоком нашёлся колокольчик. Ёж его снял, а потом повесил обратно: теперь его слышно на поворотах.",
        "У пня сидит жаба и раздаёт облакам имена. Одно назвала Пирожком." to "Пирожок уплыл. Жаба сказала, что такова судьба всех пирожков. Я решила с ней не спорить.",
        "Белка пытается спрятать орех в дырку на нарисованной двери." to "Оказалось, она проверяла вывеску художника. Дырка убедительная. Художник получил самый строгий комплимент.",
        "Крот ищет тень. Уверяет, что утром она была длиннее." to "Мы нашли тень под кустом. Чья — не разобрались, но кроту подошла. Он устроил там обед.",
        "Птичка учит свистеть чайник. Пока лучше получается у чайника." to "Чайник сняли с огня, и птичка выиграла соревнование. Я видела хитрость, но победительница была очень довольна.",
        "У дорожки сапожник сушит один крошечный сапог. Второй будто бы сбежал." to "Второй сапог оказался цветочным горшком на окне. Сапожник решил дать ему новую профессию.",
        "Бабочка села на моё ухо. Я теперь транспорт. Тариф ещё не придумала." to "Она слетела у цветка. Платой считаю то, что я ни разу не чихнула. Очень ответственная поездка.",
        "Воробей караулит пустую коробку. Говорит, там спрятана тишина." to "Я послушала. Тишину испортил его собственный живот. Мы признали, что коробку пора использовать для крошек.",
        "Заяц репетирует грозный рык. Получается икота. Очень внезапная." to "Я икнула в ответ. Мы оба засмеялись, и заяц решил пугать морковку. Она хотя бы не смеётся.",
        "На ветке висит варежка. Рядом жук объявил её гостиницей." to "Постоялец оказался один: сам жук. Зато все комнаты свободны. Я пожелала ему хорошего сезона."
    )
    fun notes(journey: Int): List<String> = encounters[Math.floorMod(journey, encounters.size)].let { listOf(it.first, it.second) }
    fun visibleCount(start: Long, now: Long): Int {
        if (start <= 0) return 0
        val elapsed = (now-start).coerceAtLeast(0)
        return if (elapsed >= 40*60_000L) 2 else if (elapsed >= 15*60_000L) 1 else 0
    }
    val snacks = listOf("Не выбрано", "Яблочные дольки", "Медовое печенье", "Лесные ягоды")
    val greetings = listOf("Не выбрано", "Ну что, рыжая, рассказывай!", "С возвращением, путешественница!", "Хвост дома — всё в порядке!")
}
